-- 0229 Limpieza de basura colada en monumentos PDF (553 entidades blog/publicidad/meta)
-- + borrado huérfano 40100 + capitalización de descripciones

DELETE FROM entidades WHERE fuente='inventario_monumentos_pdf' AND ( nombre LIKE 'Provincia de %' OR nombre LIKE 'Análisis Atómico%' OR nombre LIKE 'Próxima provincia%' OR nombre LIKE 'Punto de arranque%' OR nombre LIKE 'Comunidad %' OR nombre LIKE 'Lote %' OR nombre LIKE 'Hoja %' OR nombre LIKE '%Inventario%' OR nombre LIKE 'Estado %' OR nombre LIKE 'Pueblos en %' OR nombre LIKE 'Qué ver%' OR nombre LIKE 'Qué visitar%' OR nombre LIKE 'Qué hacer%' OR nombre LIKE 'Recorrer %' OR nombre LIKE 'Ruta %' OR nombre LIKE 'Los visitantes%' OR nombre LIKE 'Este pueblo%' OR nombre LIKE '%Mapy%' OR nombre LIKE '%Wikipedia%' OR nombre LIKE '%http%' OR nombre LIKE '%ANDORREANDO%' OR nombre LIKE '%idioma único%' OR nombre LIKE '%Véanse también%' OR nombre LIKE 'INFORMACIÓN %' OR nombre LIKE '%Normas %' OR nombre LIKE '%«%' OR nombre LIKE '%»%' OR LENGTH(nombre) > 100 OR nombre GLOB '*20[12][0-9] —*' OR nombre GLOB '* [a-z][a-z][a-z] 20[12][0-9]*' OR descripcion LIKE '%Análisis Atómico%' OR descripcion LIKE '%Próxima provincia%' OR descripcion LIKE '%Punto de arranque%' OR descripcion LIKE '%Puntuación%' OR descripcion LIKE '%Mapy%' OR descripcion LIKE '%Wikipedia%' OR descripcion LIKE '%http%' OR descripcion LIKE '%www.%' OR descripcion LIKE 'Qué ver%' OR descripcion LIKE 'Pueblos en %' OR descripcion LIKE '%Provincias Completadas%' OR descripcion LIKE '%Provincias en Desarrollo%' ) ;
DELETE FROM puntuaciones WHERE categoria='monumentos' AND codigo_ine='40100';
UPDATE entidades SET descripcion = UPPER(substr(descripcion,1,1)) || substr(descripcion,2) WHERE fuente='inventario_monumentos_pdf' AND descripcion GLOB '[a-z]*';
